// Calculate week date ranges in Eastern time
const now = new Date();

// Most recent completed week: Mon-Sun
// Since we run Monday morning, "last week" = 7 days ago Mon -> Sun
const dayOfWeek = now.getDay(); // 0=Sun, 1=Mon
const daysToLastMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

// This past Monday (start of current week)
const thisWeekStart = new Date(now);
thisWeekStart.setDate(now.getDate() - daysToLastMonday);
thisWeekStart.setHours(0, 0, 0, 0);

// Last week = prior Mon-Sun
const lastWeekStart = new Date(thisWeekStart);
lastWeekStart.setDate(thisWeekStart.getDate() - 7);
const lastWeekEnd = new Date(thisWeekStart);

// Week before that (for WoW comparison)
const priorWeekStart = new Date(lastWeekStart);
priorWeekStart.setDate(lastWeekStart.getDate() - 7);
const priorWeekEnd = new Date(lastWeekStart);

// 30 days ago for overdue threshold
const thirtyDaysAgo = new Date(now);
thirtyDaysAgo.setDate(now.getDate() - 30);

const fmt = (d) => d.toISOString().split('T')[0];

return [{
  json: {
    lastWeekStart: fmt(lastWeekStart),
    lastWeekEnd: fmt(lastWeekEnd),
    priorWeekStart: fmt(priorWeekStart),
    priorWeekEnd: fmt(priorWeekEnd),
    thirtyDaysAgo: fmt(thirtyDaysAgo),
    reportLabel: `${fmt(lastWeekStart)} – ${new Date(lastWeekEnd.getTime() - 86400000).toISOString().split('T')[0]}`,
    generatedAt: now.toISOString()
  }
}];

// Aggregate current week + prior week data for the report
const dates = $('Calculate Date Ranges').item.json;
const currentWeek = $('Fetch Last Week Invoices').all().map(i => i.json);
const priorWeek = $('Fetch Prior Week Invoices').all().map(i => i.json);
const overdue = $('Fetch Overdue Invoices (>30d)').all().map(i => i.json);

const fmt$ = (cents) => `$${(cents / 100).toFixed(2)}`;
const pct = (a, b) => b === 0 ? 'N/A' : `${((a - b) / b * 100).toFixed(1)}%`;
const arrow = (a, b) => a >= b ? '▲' : '▼';

// --- Revenue by service type (current week) ---
const serviceMap = {};
for (const inv of currentWeek) {
  const svc = inv.job?.service_type || 'Unknown';
  if (!serviceMap[svc]) serviceMap[svc] = { invoiced: 0, paid: 0, count: 0 };
  serviceMap[svc].invoiced += inv.total_cents || 0;
  serviceMap[svc].paid += inv.amount_paid_cents || 0;
  serviceMap[svc].count += 1;
}

// --- Lead source counts (current week) ---
const sourceMap = {};
for (const inv of currentWeek) {
  const src = inv.job?.source || 'Unknown';
  if (!sourceMap[src]) sourceMap[src] = 0;
  sourceMap[src] += 1;
}

// --- Totals ---
const totalInvoiced = currentWeek.reduce((s, i) => s + (i.total_cents || 0), 0);
const totalPaid = currentWeek.reduce((s, i) => s + (i.amount_paid_cents || 0), 0);
const totalOutstanding = totalInvoiced - totalPaid;
const invoiceCount = currentWeek.length;

const priorInvoiced = priorWeek.reduce((s, i) => s + (i.total_cents || 0), 0);
const priorPaid = priorWeek.reduce((s, i) => s + (i.amount_paid_cents || 0), 0);
const priorCount = priorWeek.length;

// --- Overdue summary ---
const overdueTotal = overdue.reduce((s, i) => s + (i.balance_due_cents || 0), 0);

// Build service type rows
const serviceRows = Object.entries(serviceMap)
  .sort((a, b) => b[1].invoiced - a[1].invoiced)
  .map(([svc, d]) => `| ${svc} | ${d.count} | ${fmt$(d.invoiced)} | ${fmt$(d.paid)} |`)
  .join('\n');

// Build lead source rows
const sourceRows = Object.entries(sourceMap)
  .sort((a, b) => b[1] - a[1])
  .map(([src, cnt]) => `| ${src} | ${cnt} |`)
  .join('\n');

// Build overdue rows (top 10)
const overdueRows = overdue.slice(0, 10)
  .map(i => {
    const daysAgo = Math.floor((Date.now() - new Date(i.due_date).getTime()) / 86400000);
    return `| #${i.invoice_number} | ${i.customer_name} | ${fmt$(i.balance_due_cents)} | ${i.due_date} | ${daysAgo}d |`;
  })
  .join('\n');

const wowRevPct = pct(totalInvoiced, priorInvoiced);
const wowRevArrow = arrow(totalInvoiced, priorInvoiced);
const wowJobPct = pct(invoiceCount, priorCount);
const wowJobArrow = arrow(invoiceCount, priorCount);

const report = `# Weekly Financial Report
**Period:** ${dates.reportLabel}
**Generated:** ${new Date(dates.generatedAt).toLocaleString('en-US', {timeZone: 'America/New_York'})}

---

## Executive Summary

| Metric | This Week | Prior Week | Change |
|--------|-----------|------------|--------|
| Total Invoiced | ${fmt$(totalInvoiced)} | ${fmt$(priorInvoiced)} | ${wowRevArrow} ${wowRevPct} |
| Total Collected | ${fmt$(totalPaid)} | ${fmt$(priorPaid)} | ${arrow(totalPaid, priorPaid)} ${pct(totalPaid, priorPaid)} |
| # Invoices | ${invoiceCount} | ${priorCount} | ${wowJobArrow} ${wowJobPct} |
| Outstanding (this week) | ${fmt$(totalOutstanding)} | — | — |
| Avg Invoice Value | ${invoiceCount > 0 ? fmt$(Math.round(totalInvoiced / invoiceCount)) : '$0'} | ${priorCount > 0 ? fmt$(Math.round(priorInvoiced / priorCount)) : '$0'} | — |

---

## Revenue by Service Type

| Service Type | # Jobs | Invoiced | Collected |
|-------------|--------|----------|----------|
${serviceRows || '| No data | — | — | — |'}

---

## Leads by Source (This Week)

| Channel | # Leads |
|---------|---------|
${sourceRows || '| No data | — |'}

---

## Outstanding Invoices >30 Days

**Total overdue balance: ${fmt$(overdueTotal)} across ${overdue.length} invoice(s)**

| Invoice # | Customer | Balance | Due Date | Days Overdue |
|-----------|----------|---------|----------|--------------|
${overdueRows || '| — | No overdue invoices | — | — | — |'}
${overdue.length > 10 ? `\n_...and ${overdue.length - 10} more overdue invoices not shown._` : ''}

---
_Automated report from Operations Agent — Murray's AI Command Center_`;

return [{
  json: {
    report,
    summary: {
      totalInvoiced,
      totalPaid,
      overdueTotal,
      invoiceCount,
      wowRevPct,
      wowRevArrow
    },
    dates
  }
}];

const result = $input.first().json;
const summary = $('Aggregate & Build Report').item.json.summary;
const fmt$ = (cents) => `$${(cents / 100).toFixed(2)}`;

console.log('Weekly financial report delivered to CEO Agent');
console.log(`Issue ID: ${result.id} | Identifier: ${result.identifier}`);
console.log(`Revenue: ${fmt$(summary.totalInvoiced)} (${summary.wowRevArrow} ${summary.wowRevPct} WoW)`);
console.log(`Overdue: ${fmt$(summary.overdueTotal)}`);

return [{ json: { success: true, issueId: result.id, identifier: result.identifier } }];
